use std::collections::{HashMap, HashSet};

use anyhow::Result;
use yellowstone_grpc_proto::prelude::SubscribeUpdateTransaction;

use crate::{NormalizedSwapV1, SwapExtractor, TxContext};

/// Decoder function signature generated by `normalizer-generated`.
pub type InstructionDecoderFn = fn(
    data: &[u8],
    account_indices: &[u8],
    account_keys: &[String],
) -> Option<(String, HashMap<String, String>)>;

/// Extract all normalized swaps from a geyser `SubscribeUpdateTransaction`.
///
/// * `extractors` – generated swap extractors (from `normalizer-generated::registry()`)
/// * `decoder_for` – lookup closure returning the instruction decoder for a program ID
/// * `block_time_unix` – optional block time to stamp into the output payload
pub fn extract_swaps_from_update<F>(
    update: &SubscribeUpdateTransaction,
    extractors: &[Box<dyn SwapExtractor>],
    decoder_for: &F,
    block_time_unix: Option<i64>,
) -> Result<Vec<NormalizedSwapV1>>
where
    F: Fn(&str) -> Option<InstructionDecoderFn>,
{
    let mut swaps = Vec::new();

    let Some(info) = update.transaction.as_ref() else {
        return Ok(swaps);
    };

    let Some(inner) = info.transaction.as_ref() else {
        return Ok(swaps);
    };

    let Some(message) = inner.message.as_ref() else {
        return Ok(swaps);
    };

    let account_keys: Vec<String> = message
        .account_keys
        .iter()
        .map(|k| bs58::encode(k).into_string())
        .collect();

    let token_changes = collect_token_balance_changes(info, &account_keys);
    let signature_b58 = bs58::encode(&info.signature).into_string();
    let slot = update.slot;
    let block_time = block_time_unix.unwrap_or(0);
    let meta_success = info.meta.as_ref().map(|m| m.err.is_none()).unwrap_or(false);

    for (ix_index, instruction) in message.instructions.iter().enumerate() {
        let pid_index = instruction.program_id_index as usize;
        if pid_index >= account_keys.len() {
            continue;
        }

        let program_id = &account_keys[pid_index];
        let decoded = decoder_for(program_id)
            .and_then(|decoder| decoder(&instruction.data, &instruction.accounts, &account_keys));

        let (decoded_name, decoded_roles) = match decoded {
            Some((name, roles)) => (Some(name), Some(roles)),
            None => (None, None),
        };

        let ctx = TxContext {
            slot,
            block_time_unix: block_time,
            signature: signature_b58.clone(),
            ix_index: ix_index as u16,
            program_id: program_id.clone(),
            meta_ok: meta_success,
            token_balance_changes: &token_changes,
            account_data_by_pubkey: None,
            decoded_name,
            decoded_args_json: None,
            decoded_accounts_by_role: decoded_roles.clone(),
        };

        for extractor in extractors
            .iter()
            .filter(|ex| ex.program_id() == program_id.as_str())
        {
            if let Some(mut swap) = extractor.try_extract(&ctx) {
                // Normalise mandatory fields in case extractor left defaults.
                swap.slot = slot;
                swap.block_time_unix = block_time;
                swap.signature = signature_b58.clone();
                swap.program_id = program_id.clone();

                if swap.pool_id.is_empty() {
                    if let Some(roles) = decoded_roles.as_ref() {
                        if let Some(pool) = roles
                            .get("whirlpool")
                            .or_else(|| roles.get("pool"))
                            .or_else(|| roles.get("market"))
                        {
                            swap.pool_id = pool.clone();
                        }
                    }
                }

                if swap.pool_id.is_empty() {
                    if let Some(first_idx) = instruction.accounts.first() {
                        if let Some(pk) = account_keys.get(*first_idx as usize) {
                            swap.pool_id = pk.clone();
                        }
                    } else if let Some(pk) = account_keys.first() {
                        swap.pool_id = pk.clone();
                    }
                }

                swaps.push(swap);
            }
        }
    }

    Ok(swaps)
}

fn collect_token_balance_changes(
    info: &yellowstone_grpc_proto::prelude::SubscribeUpdateTransactionInfo,
    account_keys: &[String],
) -> Vec<crate::TokenBalanceChange> {
    let Some(meta) = info.meta.as_ref() else {
        return Vec::new();
    };

    let mut pre_map: HashMap<(String, String), u128> = HashMap::new();
    let mut post_map: HashMap<(String, String), u128> = HashMap::new();
    let mut owners_mints: HashSet<(String, String)> = HashSet::new();

    for bal in &meta.pre_token_balances {
        let owner = resolve_owner(&bal.owner, bal.account_index as usize, account_keys);
        let mint = bal.mint.clone();
        let amount = bal
            .ui_token_amount
            .as_ref()
            .and_then(|uta| uta.amount.parse::<u128>().ok())
            .unwrap_or_default();
        let key = (owner, mint);
        owners_mints.insert(key.clone());
        pre_map.insert(key, amount);
    }

    for bal in &meta.post_token_balances {
        let owner = resolve_owner(&bal.owner, bal.account_index as usize, account_keys);
        let mint = bal.mint.clone();
        let amount = bal
            .ui_token_amount
            .as_ref()
            .and_then(|uta| uta.amount.parse::<u128>().ok())
            .unwrap_or_default();
        let key = (owner, mint);
        owners_mints.insert(key.clone());
        post_map.insert(key, amount);
    }

    owners_mints
        .into_iter()
        .filter_map(|(owner, mint)| {
            let key = (owner.clone(), mint.clone());
            let pre = pre_map.get(&key).copied().unwrap_or(0);
            let post = post_map.get(&key).copied().unwrap_or(0);
            if pre == 0 && post == 0 {
                return None;
            }
            if pre == post {
                return None;
            }
            Some(crate::TokenBalanceChange {
                owner,
                mint,
                pre,
                post,
            })
        })
        .collect()
}

fn resolve_owner(owner: &str, idx: usize, account_keys: &[String]) -> String {
    if owner.is_empty() {
        account_keys
            .get(idx)
            .cloned()
            .unwrap_or_else(|| "unknown".to_string())
    } else {
        owner.to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{QualityFlags, SwapKind};
    use std::collections::HashMap;
    use yellowstone_grpc_proto::prelude as ypp;
    use yellowstone_grpc_proto::solana::storage::confirmed_block::{
        CompiledInstruction as BlockCompiledInstruction, Message as BlockMessage,
        Transaction as BlockTransaction,
    };
    use ypp::{SubscribeUpdateTransaction, SubscribeUpdateTransactionInfo};

    const TEST_PROGRAM_ID: &str = "11111111111111111111111111111111";

    struct DummyExtractor;

    impl SwapExtractor for DummyExtractor {
        fn program_id(&self) -> &str {
            TEST_PROGRAM_ID
        }

        fn try_extract(&self, ctx: &TxContext) -> Option<NormalizedSwapV1> {
            Some(NormalizedSwapV1 {
                slot: ctx.slot,
                block_time_unix: ctx.block_time_unix,
                signature: ctx.signature.clone(),
                ix_index: ctx.ix_index,
                program_id: ctx.program_id.clone(),
                dex: "testdex".to_string(),
                pool_id: String::new(),
                swap_kind: SwapKind::Other,
                token_in_mint: "AAA".into(),
                token_out_mint: "BBB".into(),
                amount_in: 1,
                amount_out: 2,
                fee_bps_estimate: Some(5),
                price: 2.0,
                tick_index: None,
                sqrt_price_x64: None,
                user_authority: None,
                success: ctx.meta_ok,
                quality: QualityFlags::default(),
            })
        }
    }

    fn test_decoder_fn(
        _data: &[u8],
        _account_indices: &[u8],
        _account_keys: &[String],
    ) -> Option<(String, HashMap<String, String>)> {
        let mut roles = HashMap::new();
        roles.insert("pool".to_string(), "POOL123".to_string());
        Some(("swap".to_string(), roles))
    }

    #[test]
    #[allow(clippy::needless_update)]
    fn empty_update_returns_no_swaps() {
        let update = SubscribeUpdateTransaction {
            slot: 42,
            transaction: Some(SubscribeUpdateTransactionInfo {
                signature: vec![],
                transaction: Some(BlockTransaction {
                    message: None,
                    ..Default::default()
                }),
                meta: None,
                ..Default::default()
            }),
            ..Default::default()
        };

        let swaps = extract_swaps_from_update(&update, &[], &|_| None, None).unwrap();
        assert!(swaps.is_empty());
    }

    #[test]
    #[allow(clippy::needless_update)]
    fn extracts_swap_and_uses_decoder_roles() {
        let instruction = BlockCompiledInstruction {
            program_id_index: 0,
            accounts: vec![0],
            data: vec![1, 2, 3, 4],
        };

        let message = BlockMessage {
            account_keys: vec![bs58::decode(TEST_PROGRAM_ID).into_vec().unwrap()],
            instructions: vec![instruction],
            ..Default::default()
        };

        let info = SubscribeUpdateTransactionInfo {
            signature: vec![0; 64],
            transaction: Some(BlockTransaction {
                message: Some(message),
                ..Default::default()
            }),
            meta: None,
            ..Default::default()
        };

        let update = SubscribeUpdateTransaction {
            slot: 123,
            transaction: Some(info),
            ..Default::default()
        };

        let extractors: Vec<Box<dyn SwapExtractor>> = vec![Box::new(DummyExtractor)];
        let decoder_lookup = |pid: &str| {
            if pid == TEST_PROGRAM_ID {
                Some(test_decoder_fn as InstructionDecoderFn)
            } else {
                None
            }
        };

        let swaps =
            extract_swaps_from_update(&update, &extractors, &decoder_lookup, Some(10)).unwrap();
        assert_eq!(swaps.len(), 1);
        let swap = &swaps[0];
        assert_eq!(swap.pool_id, "POOL123");
        assert_eq!(swap.slot, 123);
        assert_eq!(swap.block_time_unix, 10);
        assert_eq!(swap.dex, "testdex");
    }
}
